 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The colored full lines partition the canvas into panels.
    row_cuts = [r for r, row in enumerate(grid)
                if row[0] != 0 and all(v == row[0] for v in row)]
    col_cuts = [c for c in range(w)
                if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(size, cuts):
        result, start = [], 0
        for cut in cuts:
            result.append((start, cut))
            start = cut + 1
        result.append((start, size))
        return result

    rows, cols = spans(h, row_cuts), spans(w, col_cuts)
    nr, nc = len(rows), len(cols)

    def panel_mask(pr, pc, color):
        r0, r1 = rows[pr]
        c0, c1 = cols[pc]
        return [[int(grid[r][c] == color) for c in range(c0, c1)]
                for r in range(r0, r1)]

    def reflected(mask, flip_v, flip_h):
        a = [line[:] for line in mask]
        if flip_v:
            a.reverse()
        if flip_h:
            a = [line[::-1] for line in a]
        return a

    # Each 2x2 panel motif is reflected across its horizontal and vertical
    # midlines. When three matching copies are present, draw the fourth.
    additions = []
    colors = {v for row in grid for v in row if v not in (0,)}
    divider_colors = {grid[r][0] for r in row_cuts} | {grid[0][c] for c in col_cuts}
    colors -= divider_colors
    for pr in range(nr - 1):
        for pc in range(nc - 1):
            dims = [(rows[pr + dr][1] - rows[pr + dr][0],
                     cols[pc + dc][1] - cols[pc + dc][0])
                    for dr in range(2) for dc in range(2)]
            if len(set(dims)) != 1:
                continue
            ph, pw = dims[0]
            if not ph or not pw:
                continue
            for color in colors:
                masks = {}
                for dr in range(2):
                    for dc in range(2):
                        mask = panel_mask(pr + dr, pc + dc, color)
                        if any(any(line) for line in mask):
                            masks[(dr, dc)] = mask
                if len(masks) != 3:
                    continue
                missing = next((pos for pos in ((0, 0), (0, 1), (1, 0), (1, 1))
                                if pos not in masks), None)
                canonical = None
                consistent = True
                for (dr, dc), mask in masks.items():
                    candidate = reflected(mask, bool(dr), bool(dc))
                    if canonical is None:
                        canonical = candidate
                    elif candidate != canonical:
                        consistent = False
                        break
                if not consistent or missing is None:
                    continue
                target = reflected(canonical, bool(missing[0]), bool(missing[1]))
                r0 = rows[pr + missing[0]][0]
                c0 = cols[pc + missing[1]][0]
                additions.append((r0, c0, target, color))

    for r0, c0, mask, color in additions:
        for dr, line in enumerate(mask):
            for dc, value in enumerate(line):
                if value:
                    out[r0 + dr][c0 + dc] = color
    return out
